//! ISP
//! ISP Peripheral

#![allow(dead_code)]

pub const BASE: u32 = 0x500a1000;

/// VER_DATE Register
///
/// version control register
///
/// Address offset: 0x0000
/// Reset value: 0x20210608
///
/// ## Fields
///
/// - **VER_DATA** `[31:0]` (RW)
///
///   csv version
#[repr(transparent)]
pub struct VerDate {
    value: crate::common::VolatileCell<u32>,
}

impl core::ops::Deref for VerDate {
    type Target = crate::common::VolatileCell<u32>;
    #[inline(always)]
    fn deref(&self) -> &Self::Target {
        &self.value
    }
}

impl VerDate {
    // ======== Field Constants ========

    /// **VER_DATA**
    ///
    /// csv version
    ///
    /// Bits `[31:0]`, mask `0xffffffff`
    pub const VER_DATA_OFFSET: u32 = 0;
    pub const VER_DATA_MASK: u32 = 0xffffffff;

    // ======== Field Accessors ========

    /// **VER_DATA** `[31:0]` (RW)
    ///
    /// csv version
    #[inline(always)]
    pub fn ver_data(&self) -> u32 {
        (self.value.read_bits() & Self::VER_DATA_MASK) >> Self::VER_DATA_OFFSET
    }

    /// Write **VER_DATA** `[31:0]` (RW)
    ///
    /// csv version
    #[inline(always)]
    pub fn write_ver_data(&self, value: u32) {
        self.value.modify_bits(|r| {
            (r & !Self::VER_DATA_MASK) | ((value << Self::VER_DATA_OFFSET) & Self::VER_DATA_MASK)
        });
    }
}

/// VER_DATE value type for batch read/modify/write operations
///
/// Use `verdate.read_val()` to read the register into this struct,
/// modify fields with builder methods, then write back with `verdate.write_val(val)`.
#[derive(Clone, Copy)]
pub struct VerDateVal {
    bits: u32,
}

impl VerDateVal {
    /// Create from raw bits
    #[inline(always)]
    pub const fn from_bits(bits: u32) -> Self {
        Self { bits }
    }

    /// Get the raw bits
    #[inline(always)]
    pub const fn bits(&self) -> u32 {
        self.bits
    }

    /// Create with reset value
    #[inline(always)]
    pub const fn reset_val() -> Self {
        Self { bits: 0x20210608 }
    }

    /// Read **VER_DATA** `[31:0]`
    ///
    /// csv version
    #[inline(always)]
    pub const fn ver_data(&self) -> u32 {
        (self.bits & VerDate::VER_DATA_MASK) >> VerDate::VER_DATA_OFFSET
    }

    /// Set **VER_DATA** `[31:0]`
    ///
    /// csv version
    #[inline(always)]
    pub const fn with_ver_data(self, value: u32) -> Self {
        Self {
            bits: (self.bits & !VerDate::VER_DATA_MASK)
                | ((value << VerDate::VER_DATA_OFFSET) & VerDate::VER_DATA_MASK),
        }
    }
}

impl Default for VerDateVal {
    fn default() -> Self {
        Self::reset_val()
    }
}

impl VerDate {
    /// Read the register into a value struct
    #[inline(always)]
    pub fn read_val(&self) -> VerDateVal {
        VerDateVal::from_bits(self.value.read_bits())
    }

    /// Write a value struct to the register
    #[inline(always)]
    pub fn write_val(&self, val: VerDateVal) {
        self.value.write_bits(val.bits())
    }

    /// Modify the register using a value struct
    #[inline(always)]
    pub fn modify_val<F: FnOnce(VerDateVal) -> VerDateVal>(&self, f: F) {
        self.write_val(f(self.read_val()))
    }
}

/// CLK_EN Register
///
/// isp clk control register
///
/// Address offset: 0x0004
///
/// ## Fields
///
/// - **ISP_MEM_CLK_FORCE_ON** `[18]` (RW)
///
///   this bit configures the clk force on of all isp memory. 0: disable, 1: enable
///
/// - **CLK_MIPI_IDI_FORCE_ON** `[17]` (RW)
///
///   this bit configures the clk force on of mipi idi input. 0: disable, 1: enable
///
/// - **CLK_HIST_FORCE_ON** `[16]` (RW)
///
///   this bit configures the clk force on of hist. 0: disable, 1: enable
///
/// - **CLK_AWB_FORCE_ON** `[15]` (RW)
///
///   this bit configures the clk force on of awb. 0: disable, 1: enable
///
/// - **CLK_AF_FORCE_ON** `[14]` (RW)
///
///   this bit configures the clk force on of af. 0: disable, 1: enable
///
/// - **CLK_AE_FORCE_ON** `[13]` (RW)
///
///   this bit configures the clk force on of ae. 0: disable, 1: enable
///
/// - **CLK_YUV2RGB_FORCE_ON** `[12]` (RW)
///
///   this bit configures the clk force on of yuv2rgb. 0: disable, 1: enable
///
/// - **CLK_COLOR_FORCE_ON** `[11]` (RW)
///
///   this bit configures the clk force on of color. 0: disable, 1: enable
///
/// - **CLK_SHARP_FORCE_ON** `[10]` (RW)
///
///   this bit configures the clk force on of sharp. 0: disable, 1: enable
///
/// - **CLK_RGB2YUV_FORCE_ON** `[9]` (RW)
///
///   this bit configures the clk force on of rgb2yuv. 0: disable, 1: enable
///
/// - **CLK_GAMMA_FORCE_ON** `[8]` (RW)
///
///   this bit configures the clk force on of gamma. 0: disable, 1: enable
///
/// - **CLK_CCM_FORCE_ON** `[7]` (RW)
///
///   this bit configures the clk force on of ccm. 0: disable, 1: enable
///
/// - **CLK_MEDIAN_FORCE_ON** `[6]` (RW)
///
///   this bit configures the clk force on of median. 0: disable, 1: enable
///
/// - **CLK_DEMOSAIC_FORCE_ON** `[5]` (RW)
///
///   this bit configures the clk force on of demosaic. 0: disable, 1: enable
///
/// - **CLK_LSC_FORCE_ON** `[4]` (RW)
///
///   this bit configures the clk force on of lsc. 0: disable, 1: enable
///
/// - **CLK_BF_FORCE_ON** `[3]` (RW)
///
///   this bit configures the clk force on of bf. 0: disable, 1: enable
///
/// - **CLK_DPC_FORCE_ON** `[2]` (RW)
///
///   this bit configures the clk force on of dpc. 0: disable, 1: enable
///
/// - **CLK_BLC_FORCE_ON** `[1]` (RW)
///
///   this bit configures the clk force on of blc. 0: disable, 1: enable
///
/// - **CLK_EN** `[0]` (RW)
///
///   this bit configures the clk force on of isp reg. 0: disable, 1: enable
#[repr(transparent)]
pub struct ClkEn {
    value: crate::common::VolatileCell<u32>,
}

impl core::ops::Deref for ClkEn {
    type Target = crate::common::VolatileCell<u32>;
    #[inline(always)]
    fn deref(&self) -> &Self::Target {
        &self.value
    }
}

