/// AE_CTRL Register
///
/// ae control register
///
/// Address offset: 0x00c0
///
/// ## Fields
///
/// - **AE_SELECT** `[1]` (RW)
///
///   this field configures ae input data source, 0: data from median, 1: data from gama
///
/// - **AE_UPDATE** `[0]` (WO)
///
///   write 1 to this bit triggers one statistic event
#[repr(transparent)]
pub struct AeCtrl {
    value: crate::common::VolatileCell<u32>,
}

impl core::ops::Deref for AeCtrl {
    type Target = crate::common::VolatileCell<u32>;
    #[inline(always)]
    fn deref(&self) -> &Self::Target {
        &self.value
    }
}

impl AeCtrl {
    // ======== Field Constants ========

    /// **AE_SELECT**
    ///
    /// this field configures ae input data source, 0: data from median, 1: data from gama
    ///
    /// Bits `[1:1]`, mask `0x00000002`
    pub const AE_SELECT_OFFSET: u32 = 1;
    pub const AE_SELECT_MASK: u32 = 0x00000002;
    pub const AE_SELECT: u32 = 1 << 1;

    /// **AE_UPDATE**
    ///
    /// write 1 to this bit triggers one statistic event
    ///
    /// Bits `[0:0]`, mask `0x00000001`
    pub const AE_UPDATE_OFFSET: u32 = 0;
    pub const AE_UPDATE_MASK: u32 = 0x00000001;
    pub const AE_UPDATE: u32 = 1 << 0;

    // ======== Field Accessors ========

    /// **AE_SELECT** `[1]` (RW)
    ///
    /// this field configures ae input data source, 0: data from median, 1: data from gama
    #[inline(always)]
    pub fn ae_select(&self) -> bool {
        (self.value.read_bits() & Self::AE_SELECT_MASK) != 0
    }

    /// Set AE_SELECT bit (RW) - NOT atomic
    #[inline(always)]
    pub fn set_ae_select(&self) {
        self.value.modify_bits(|r| r | Self::AE_SELECT_MASK);
    }

    /// Clear AE_SELECT bit (RW) - NOT atomic
    #[inline(always)]
    pub fn clr_ae_select(&self) {
        self.value.modify_bits(|r| r & !Self::AE_SELECT_MASK);
    }

    /// Trigger **AE_UPDATE** (WO)
    ///
    /// write 1 to this bit triggers one statistic event
    #[inline(always)]
    pub fn trigger_ae_update(&self) {
        self.value.modify_bits(|r| r | Self::AE_UPDATE_MASK);
    }
}

